import React from 'react';

function LoginForm() {
    // Dựa trên phần Đăng Nhập trong HTML
    return (
        <div className="login-form-wrapper">
            <div className="text-wrapper-10">ĐĂNG NHẬP</div>
            <form>
                <p className="p">Tên tài khoản hoặc địa chỉ email *</p>
                <div className="rectangle-4"><input type="text" /></div>

                <div className="text-wrapper-14">Mật Khẩu *</div>
                <div className="rectangle-5"><input type="password" /></div>
                
                <div className="login-options">
                    <div className="rectangle-14">
                        <button className="text-wrapper-17">Đăng Nhập</button>
                    </div>
                    <div className="text-wrapper-11"><input type="checkbox" /> Nhớ Mật Khẩu</div>
                    <div className="text-wrapper-12"><a href="#">Quên mật khẩu ?</a></div>
                </div>
            </form>
        </div>
    );
}

export default LoginForm;
